python3 << 'PYEOF'
import os, re
from collections import defaultdict

ROOT = "/bench/repo"
STORE_PREFIX = os.path.join(ROOT, "store")

# Persistent entity types defined in store/*.go (main structs, not Find/Delete/Update helpers)
ENTITY_TYPES = [
    "Attachment", "User", "Memo", "Reaction", "Inbox", "IdentityProvider",
    "InstanceSetting", "MemoRelation", "MemoShare", "UserIdentity", "UserSetting",
    "AuthenticationConfigState", "AuthenticationConfigMutation",
]

# Also proto/gen/store entity types
PROTO_ENTITY_TYPES = [
    "MemoPayload", "AttachmentPayload", "IdentityProvider", "InstanceSetting",
    "UserSetting", "InboxMessage",
]

def get_package_dir(filepath):
    """Return Go package directory (parent of .go file)."""
    return os.path.dirname(filepath)

def is_in_store_layer(pkg_dir):
    rel = os.path.relpath(pkg_dir, ROOT)
    return rel == "store" or rel.startswith("store/")

def scan_files():
    files = []
    for dirpath, dirnames, filenames in os.walk(ROOT):
        if ".git" in dirnames:
            dirnames.remove(".git")
        for fn in filenames:
            if fn.endswith(".go"):
                files.append(os.path.join(dirpath, fn))
    return files

files = scan_files()
outside_files = [f for f in files if not is_in_store_layer(get_package_dir(f))]

# Count distinct packages per store entity type
store_entity_pkgs = {t: set() for t in ENTITY_TYPES}
storepb_entity_pkgs = {t: set() for t in PROTO_ENTITY_TYPES}

# Patterns
store_pat = re.compile(r'\bstore\.(' + '|'.join(ENTITY_TYPES) + r')\b')
storepb_pat = re.compile(r'\bstorepb\.(' + '|'.join(PROTO_ENTITY_TYPES) + r')\b')

for fpath in outside_files:
    pkg = get_package_dir(fpath)
    try:
        content = open(fpath).read()
    except:
        continue
    for m in store_pat.finditer(content):
        store_entity_pkgs[m.group(1)].add(pkg)
    for m in storepb_pat.finditer(content):
        storepb_entity_pkgs[m.group(1)].add(pkg)

def show_results(title, data):
    ranked = sorted(data.items(), key=lambda x: (-len(x[1]), x[0]))
    print(f"\n=== {title} ===")
    for t, pkgs in ranked:
        if len(pkgs) > 0:
            print(f"  {t}: {len(pkgs)} packages")
    print("\nTop 5 detail:")
    for t, pkgs in ranked[:5]:
        if len(pkgs) > 0:
            rel_pkgs = sorted(os.path.relpath(p, ROOT) for p in pkgs)
            print(f"\n  {t} ({len(pkgs)} packages):")
