success.beforeFullFileContent:
use strict;
use warnings;
my $ROOT = "/bench/repo";
my @ENTITY = qw(Attachment User Memo Reaction Inbox IdentityProvider InstanceSetting MemoRelation MemoShare UserIdentity UserSetting AuthenticationConfigState AuthenticationConfigMutation);
my @PROTO = qw(MemoPayload AttachmentPayload IdentityProvider InstanceSetting UserSetting InboxMessage);

sub walk {
  my ($dir, $files) = @_;
  opendir my $dh, $dir or return;
  my @ents = grep { $_ ne "." && $_ ne ".." } readdir $dh;
  closedir $dh;
  for my $e (@ents) {
    my $p = "$dir/$e";
    if ($e eq ".git") { next; }
    if (-d $p) { walk($p, $files); }
    elsif ($e =~ /\.go$/) { push @$files, $p; }
  }
}
my @files; walk($ROOT, \@files);

sub in_data_layer {
  my ($f) = @_;
  my $d = $f; $d =~ s/\/[^\/]+$//;
  my $rel = $d; $rel =~ s/^\Q$ROOT\E\/?//;
  return $rel eq "store" || $rel =~ /^store\// || $rel =~ /^proto\/(gen\/)?store/;
}

my %store_pkgs; for (@ENTITY) { $store_pkgs{$_} = {}; }
my %proto_pkgs; for (@PROTO) { $proto_pkgs{$_} = {}; }

my $store_re = join("|", @ENTITY);
my $proto_re = join("|", @PROTO);

for my $f (@files) {
  next if in_data_layer($f);
  my $pkg = $f; $pkg =~ s/\/[^\/]+$//;
  open my $fh, "<", $f or next;
  my $c = do { local $/; <$fh> };
  close $fh;
  while ($c =~ /\bstore\.($store_re)\b/g) { $store_pkgs{$1}{$pkg} = 1; }
  while ($c =~ /\bstorepb\.($proto_re)\b/g) { $proto_pkgs{$1}{$pkg} = 1; }
}

sub show {
  my ($title, $data) = @_;
  print "\n=== $title ===\n";
  my @ranked = sort { scalar(keys %{$data->{$b}}) <=> scalar(keys %{$data->{$a}}) || $a cmp $b } keys %$data;
  for my $t (@ranked) {
    my $n = scalar keys %{$data->{$t}};
    if ($n) { print "  $t: $n packages\n"; }
  }
  print "\nTop 5 detail:\n";
  my $i = 0;
  for my $t (@ranked) {
    my $n = scalar keys %{$data->{$t}};
    next unless $n;
    if ($i >= 5) { last; }
    $i++;
    print "\n  $t ($n packages):\n";
    for my $p (sort keys %{$data->{$t}}) {
      my $rel = $p; $rel =~ s/^\Q$ROOT\E\/?//;
      print "    - $rel\n";
    }
  }
}

show("store.* entity types (outside data layer)", \%store_pkgs);
show("storepb.* entity types (outside store layer)", \%proto_pkgs);

my %combined;
for my $t (@ENTITY, @PROTO) {
  $combined{$t} = {};
  for my $p (keys %{$store_pkgs{$t} // {}}) { $combined{$t}{$p} = 1; }
  for my $p (keys %{$proto_pkgs{$t} // {}}) { $combined{$t}{$p} = 1; }
}
show("Combined (union store + storepb per name)", \%combined);

